import{_ as t,o as i,a as e,b as l}from"./app.DKoEZOcr.js";const C=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"HCCL通信类","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_communication"},{"text":"HCCL Tiling侧接口","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/HCCL_Tiling"},{"text":"SetSkipLocalRankCopy","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetSkipLocalRankCopy"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetSkipLocalRankCopy.md","filePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetSkipLocalRankCopy.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1785895910000}'),n={name:"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetSkipLocalRankCopy.md"};function o(p,a,s,c,r,d){return i(),e("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>SetSkipLocalRankCopy</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>设置本卡的通信算法的计算结果是否输出到目的数据buffer地址。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>uint32_t SetSkipLocalRankCopy(uint8_t skipLocalRankCopy)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>skipLocalRankCopy</td><td>输入</td><td>本卡的通信算法的计算结果是否输出到recvBuf（目的数据buffer地址）。<span data-filter="910b"><br><br>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，仅AllGather算法与AlltoAll算法支持配置该参数。uint8_t类型，参数取值如下：<br>0：输出本卡通信算法的计算结果（未调用本接口时的默认行为）。<br>1：不输出本卡通信算法的计算结果。在无需输出通信结果时，配置参数值为1，此时不会拷贝本卡的通信结果数据，可提升算子性能。例如，在8卡场景下，本卡只取其他卡的部分数据，这时可配置该参数为1。</span><span data-filter="A3"><br><br>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，该参数为预留字段，配置后不生效。</span></td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><ul><li>0表示设置成功。</li><li>非0表示设置失败。</li></ul><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>无</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>本接口的调用示例请见<a href="SetOpType.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">调用示例</a>。</p></article></div>`,1)])])}const _=t(n,[["render",o]]);export{C as __pageData,_ as default};
